const TranscriptActions = createContext<{ open: (meeting: Meeting) => void; notes: (meeting: Meeting) => void; transcribe: (meeting: Meeting) => void; play: (meeting: Meeting, track: AudioTrack, startMs?: number) => void; stopPlayback: () => void; playback: PlaybackStatus | null; transcribingId: string | null }>({ open: () => undefined, notes: () => undefined, transcribe: () => undefined, play: () => undefined, stopPlayback: () => undefined, playback: null, transcribingId: null });
const humanDate = (value: string) => new Intl.DateTimeFormat(undefined, { dateStyle: "medium", timeStyle: "short" }).format(new Date(value));
const durationLabel = (value: number | null) => value ? `${Math.max(1, Math.round(value / 60_000))} min` : "Not recorded";
const byteLabel = (value: number) => value < 1024 * 1024 ? `${Math.round(value / 1024)} KB` : value < 1024 * 1024 * 1024 ? `${(value / 1024 / 1024).toFixed(1)} MB` : `${(value / 1024 / 1024 / 1024).toFixed(2)} GB`;
const transcriptionPackKey = "transcrip-it.transcription-pack";
const microphoneTrackKey = "transcrip-it.microphone-track";
const packOptions: { id: TranscriptionModelPack; label: string; size: string; detail: string }[] = [
  { id: "fast", label: "Fast English", size: "142 MB", detail: "Fastest; suitable for clear audio" },
  { id: "balanced", label: "Balanced English", size: "466 MB", detail: "Recommended accuracy and speed" },
  { id: "accuracy", label: "Accuracy English", size: "1.5 GB", detail: "Best accuracy; slower processing" },
];
const selectedTranscriptionPack = (): TranscriptionModelPack => {
  const stored = localStorage.getItem(transcriptionPackKey);
  return stored === "balanced" || stored === "accuracy" ? stored : "fast";
};
const selectedMicrophoneTrack = (): MicrophoneTrack => localStorage.getItem(microphoneTrackKey) === "mic" ? "mic" : "mic_raw";
type MeetingFilters = { query: string; status: "all" | Meeting["state"]; tag: string; participant: string; dateRange: "all" | "today" | "7" | "30" };
export const meetingMatchesFilters = (meeting: Meeting, filters: MeetingFilters, now = Date.now()) => {
  const query = filters.query.trim().toLowerCase();
  if (query && !`${meeting.title} ${meeting.tags.join(" ")} ${meeting.participantLabels?.join(" ") ?? ""}`.toLowerCase().includes(query)) return false;
  if (filters.status !== "all" && meeting.state !== filters.status) return false;
  if (filters.tag && !meeting.tags.some((tag) => tag.toLowerCase() === filters.tag.toLowerCase())) return false;
  if (filters.participant && !(meeting.participantLabels ?? []).some((label) => label.toLowerCase() === filters.participant.toLowerCase())) return false;
  if (filters.dateRange !== "all") {
    const current = new Date(now);
    const threshold = filters.dateRange === "today"
      ? new Date(current.getFullYear(), current.getMonth(), current.getDate()).getTime()
      : now - Number(filters.dateRange) * 24 * 60 * 60 * 1000;
    if (new Date(meeting.createdAt).getTime() < threshold) return false;
  }
  return true;
};

function EmptyLibrary({ onRecord }: { onRecord: () => void }) {
  return <div className="empty-state"><div className="empty-visual" aria-hidden="true"><span className="paper back" /><span className="paper front"><i /><i /><i /><b><i /><i /><i /><i /><i /></b></span><span className="empty-spark one">✦</span><span className="empty-spark two">✦</span></div><h3>Your meeting library starts here</h3><p>Prepare a consented recording and it will be stored in your private local library.</p><button className="secondary-button" type="button" onClick={onRecord}><Icon name="record" size={17} /> Record your first meeting</button></div>;
}

function MeetingCard({ meeting, onChanged, onError }: { meeting: Meeting; onChanged: () => Promise<void>; onError: (value: string) => void }) {
  const transcriptActions = useContext(TranscriptActions);
  const run = async (action: () => Promise<unknown>) => { try { await action(); await onChanged(); } catch (error) { onError(String(error)); } };
  const rename = () => { const title = window.prompt("Meeting title", meeting.title); if (title?.trim() && title.trim() !== meeting.title) void run(() => meetingApi.rename(meeting.id, title)); };
  const editTags = () => { const value = window.prompt("Comma-separated tags", meeting.tags.join(", ")); if (value !== null) void run(() => meetingApi.replaceTags(meeting.id, value.split(","))); };
  const remove = () => { if (window.confirm(`Permanently delete “${meeting.title}” and all local data?`)) void run(() => meetingApi.delete(meeting.id)); };
  const play = (track: AudioTrack) => { const isPlaying = transcriptActions.playback?.active && transcriptActions.playback.meetingId === meeting.id && transcriptActions.playback.track === track; if (isPlaying) transcriptActions.stopPlayback(); else transcriptActions.play(meeting, track); };
  const playbackLabel = (track: AudioTrack, label: string) => transcriptActions.playback?.active && transcriptActions.playback.meetingId === meeting.id && transcriptActions.playback.track === track ? `Stop ${label}` : `Play ${label}`;
  const canDelete = !["recording", "paused", "processing"].includes(meeting.state);
  if (meeting.state === "failed" && meeting.recordingPath) {
    return <article className="meeting-card recovery-card"><div className="meeting-card-main"><div className="state-mark archived"><Icon name="record" size={18} /></div><div><div className="meeting-title-line"><h3>{meeting.title}</h3><span className="state-badge archived">recovered</span></div><p>{humanDate(meeting.createdAt)} · Safe audio chunks are available</p></div></div><div className="meeting-actions"><button type="button" className={playbackLabel("mic_raw", "original mic").startsWith("Stop") ? "playing" : ""} onClick={() => play("mic_raw")}>{playbackLabel("mic_raw", "original mic")}</button><button type="button" className={playbackLabel("mic", "echo-reduced mic").startsWith("Stop") ? "playing" : ""} onClick={() => play("mic")}>{playbackLabel("mic", "echo-reduced mic")}</button><button type="button" className={playbackLabel("system", "system").startsWith("Stop") ? "playing" : ""} onClick={() => play("system")}>{playbackLabel("system", "system")}</button><button className="prominent" type="button" disabled={transcriptActions.transcribingId === meeting.id} onClick={() => transcriptActions.transcribe(meeting)}>{transcriptActions.transcribingId === meeting.id ? "Retrying…" : "Retry transcript"}</button><button type="button" onClick={() => void run(() => meetingApi.archive(meeting.id))}>Archive</button><button className="danger" type="button" onClick={remove}>Delete meeting</button></div></article>;
  }
  return <article className="meeting-card"><div className="meeting-card-main"><div className={`state-mark ${meeting.state}`}><Icon name={meeting.state === "ready" ? "sparkles" : "record"} size={18} /></div><div><div className="meeting-title-line"><h3>{meeting.title}</h3><span className={`state-badge ${meeting.state}`}>{meeting.state}</span></div><p>{humanDate(meeting.createdAt)} · {durationLabel(meeting.durationMs)}{meeting.transcriptSegmentCount > 0 ? ` · ${meeting.transcriptSegmentCount} transcript segments` : ""}</p>{meeting.tags.length > 0 && <div className="tag-row">{meeting.tags.map((tag) => <span key={tag}>{tag}</span>)}</div>}</div></div><div className="meeting-actions">{meeting.state === "ready" && meeting.recordingPath && <><button type="button" className={playbackLabel("mic_raw", "original mic").startsWith("Stop") ? "playing" : ""} onClick={() => play("mic_raw")}>{playbackLabel("mic_raw", "original mic")}</button><button type="button" className={playbackLabel("mic", "echo-reduced mic").startsWith("Stop") ? "playing" : ""} onClick={() => play("mic")}>{playbackLabel("mic", "echo-reduced mic")}</button><button type="button" className={playbackLabel("system", "system").startsWith("Stop") ? "playing" : ""} onClick={() => play("system")}>{playbackLabel("system", "system")}</button>{meeting.transcriptSegmentCount > 0 ? <><button className="prominent" type="button" onClick={() => transcriptActions.open(meeting)}>Transcript</button><button className="prominent" type="button" onClick={() => transcriptActions.notes(meeting)}>Notes</button></> : <button className="prominent" type="button" disabled={transcriptActions.transcribingId === meeting.id} onClick={() => transcriptActions.transcribe(meeting)}>{transcriptActions.transcribingId === meeting.id ? "Transcribing…" : "Transcribe"}</button>}</>}{meeting.state !== "archived" ? <><button type="button" onClick={rename}>Rename</button><button type="button" onClick={editTags}>Tags</button><button type="button" onClick={() => void run(() => meetingApi.archive(meeting.id))}>Archive</button></> : <button type="button" onClick={() => void run(() => meetingApi.reopen(meeting.id))}>Reopen</button>}{canDelete && <button className="danger" type="button" onClick={remove}>Delete meeting</button>}</div></article>;
}

function RecordSetup({ onStart, onError, onWarnings }: { onStart: (title: string, options: StartRecordingOptions) => Promise<void>; onError: (value: string) => void; onWarnings: (value: string[]) => void }) {
  const [title, setTitle] = useState(""); const [consent, setConsent] = useState(false); const [busy, setBusy] = useState(false); const [mode, setMode] = useState<StartRecordingOptions["mode"]>("both"); const [echoCancellation, setEchoCancellation] = useState(true); const [devices, setDevices] = useState<AudioDevices | null>(null); const [micSource, setMicSource] = useState(""); const [systemSource, setSystemSource] = useState("");
  useEffect(() => { if (!recordingApi.available) return; void recordingApi.devices().then((found) => { setDevices(found); setMicSource(found.defaultSource); setSystemSource(found.systemSource ?? ""); onWarnings(found.warnings); }).catch((error) => onError(String(error))); return () => onWarnings([]); }, [onError, onWarnings]);
  const submit = async (event: FormEvent) => { event.preventDefault(); setBusy(true); try { await onStart(title.trim() || `Meeting ${new Date().toLocaleString()}`, { mode, micSource: micSource || null, systemSource: systemSource || null, echoCancellation: mode === "both" && echoCancellation }); } catch (error) { onError(String(error)); } finally { setBusy(false); } };
  return <section className="page-view record-view"><div className="page-heading"><div><p className="eyebrow">NEW RECORDING</p><h1>Prepare your meeting</h1><p>Choose audio sources and confirm consent before capture begins.</p></div></div><form className="setup-card" onSubmit={(event) => void submit(event)}><label className="field"><span>Meeting title</span><input value={title} onChange={(event) => setTitle(event.target.value)} placeholder="Weekly sync" /></label><label className="field"><span>Capture mode</span><select value={mode} onChange={(event) => setMode(event.target.value as StartRecordingOptions["mode"])}><option value="both">Microphone + system audio</option><option value="mic">Microphone only</option><option value="system">System audio only</option></select></label>{devices && mode !== "system" && <label className="field"><span>Microphone</span><select value={micSource} onChange={(event) => setMicSource(event.target.value)}>{devices.sources.filter((source) => !source.monitor).map((source) => <option value={source.name} key={source.name}>{source.name === devices.defaultSource ? `Default · ${source.name}` : source.name}</option>)}</select></label>}{devices && mode !== "mic" && <label className="field"><span>System audio</span><select value={systemSource} onChange={(event) => setSystemSource(event.target.value)}>{devices.sources.filter((source) => source.monitor).map((source) => <option value={source.name} key={source.name}>{source.name === devices.systemSource ? `Default · ${source.name}` : source.name}</option>)}</select></label>}<div className="capture-summary"><Icon name="headphones" size={24} /><div><strong>{mode === "both" ? "Microphone + system audio" : mode === "mic" ? "Microphone only" : "System audio only"}</strong><span>{mode === "both" && echoCancellation ? "WebRTC echo cancellation · headset recommended" : "Original audio is preserved locally"}</span></div></div>{mode === "both" && <label className="inline-check"><input type="checkbox" checked={echoCancellation} onChange={(event) => setEchoCancellation(event.target.checked)} /> Reduce speaker echo (recommended)</label>}<label className="consent-check"><input type="checkbox" checked={consent} onChange={(event) => setConsent(event.target.checked)} /><span><strong>I confirm everyone has consented to this recording.</strong><small>You are responsible for following applicable laws and meeting policies.</small></span></label>{!recordingApi.available && <p className="desktop-only-note">Open the Tauri desktop app to capture audio. Browser preview does not access your microphone.</p>}<button className="primary-button record-action" type="submit" disabled={!consent || busy || !recordingApi.available}><Icon name="record" size={18} />{busy ? "Starting…" : "Start recording"}</button></form></section>;
}

const clockLabel = (seconds: number) => `${String(Math.floor(seconds / 60)).padStart(2, "0")}:${String(seconds % 60).padStart(2, "0")}`;
export const latestLiveTranscriptLines = (lines: LiveTranscriptLine[], limit = 3) => lines.slice(-limit);
export const recordingWarningMessages = (status: RecordingStatus | null) => {
  if (!status) return [];
  const warnings = [...status.warnings];
  if (!status.processRunning) warnings.push("Audio capture stopped unexpectedly. Stop the recording to preserve completed chunks.");
  if (status.storageAvailableBytes !== null && status.storageAvailableBytes < 512 * 1024 * 1024) warnings.push(`Storage is running low (${Math.round(status.storageAvailableBytes / 1024 / 1024)} MB free). Capture stops safely at 128 MB.`);
  return [...new Set(warnings)];
};
function ActiveRecording({ meeting, status, liveLines, liveCheckedThroughMs, liveError, previewing, onStop, onTogglePause }: { meeting: Meeting; status: RecordingStatus; liveLines: LiveTranscriptLine[]; liveCheckedThroughMs: number; liveError: string; previewing: boolean; onStop: () => Promise<void>; onTogglePause: () => Promise<void> }) {
  const [busy, setBusy] = useState(false);
  const stop = async () => { setBusy(true); try { await onStop(); } finally { setBusy(false); } };
  const togglePause = async () => { setBusy(true); try { await onTogglePause(); } finally { setBusy(false); } };
  const microphoneTrack = selectedMicrophoneTrack();
  const visibleLines = latestLiveTranscriptLines(liveLines);
  const previewLagMs = Math.max(0, status.elapsedSeconds * 1000 - liveCheckedThroughMs);
  const previewStatus = liveCheckedThroughMs === 0 ? (previewing ? "Starting local preview…" : "Waiting for audio…") : previewing ? `Processing after ${timestampLabel(liveCheckedThroughMs)}…` : previewLagMs > 20_000 ? `Preview delayed · checked through ${timestampLabel(liveCheckedThroughMs)}` : `Caught up through ${timestampLabel(liveCheckedThroughMs)}`;
  return <section className={`recording-live${status.paused ? " paused" : ""}`} aria-live="polite"><div className="recording-pulse"><span /></div><p className="eyebrow">{status.paused ? "RECORDING PAUSED" : "RECORDING NOW"}</p><h1>{meeting.title}</h1><strong className="recording-clock">{clockLabel(status.elapsedSeconds)}</strong><p>{status.paused ? "Audio capture is paused. Resume when the conversation continues." : "Selected audio sources are being saved in recoverable local chunks."}</p>{status.levels.length > 0 && <div className="level-list" aria-label="Live audio levels">{status.levels.filter((level) => level.name === microphoneTrack || level.name === "system").map((level) => <div className="level-row" key={level.name}><span>{level.name === "system" ? "System" : microphoneTrack === "mic_raw" ? "Original mic" : "Echo-reduced mic"}</span><i><b style={{ width: `${Math.max(2, Math.round(level.peak * 100))}%` }} /></i></div>)}</div>}<section className="live-transcript" aria-label="Live transcript preview"><div className="live-transcript-heading"><div><span className="status-dot" /><strong>Live transcript</strong></div><small className={previewLagMs > 20_000 ? "delayed" : ""}>{previewStatus}</small></div><p className="live-transcript-disclaimer">Live text is a quick draft and may be delayed or inaccurate. The final transcript is reprocessed after recording.</p>{liveError ? <p className="live-transcript-placeholder">{liveError}</p> : liveLines.length === 0 ? <p className="live-transcript-placeholder">{liveCheckedThroughMs > 0 ? `No clear speech yet · audio checked through ${timestampLabel(liveCheckedThroughMs)}` : "Listening for speech…"}</p> : <><div className="live-transcript-lines">{visibleLines.map((line) => <article key={`${line.trackId}:${line.chunkIndex}:${line.windowIndex}`}><span>{timestampLabel(line.startMs)} · {line.speakerLabel}</span><p>{line.text}</p></article>)}</div>{liveLines.length > visibleLines.length && <p className="live-transcript-history">Showing the latest {visibleLines.length} passages · {liveLines.length - visibleLines.length} earlier retained for this recording</p>}</>}</section><div className="recording-controls"><button className="pause-button" type="button" disabled={busy} onClick={() => void togglePause()}>{status.paused ? "Resume" : "Pause"}</button><button className="stop-button" type="button" disabled={busy} onClick={() => void stop()}>{busy ? "Working safely…" : "Stop recording"}</button></div><small>Stopping may take a few seconds while WAV headers and the session manifest are finalized.</small></section>;
}

const timestampLabel = (milliseconds: number) => `${String(Math.floor(milliseconds / 60_000)).padStart(2, "0")}:${String(Math.floor(milliseconds / 1000) % 60).padStart(2, "0")}`;
function TranscriptDialog({ meeting, segments, onClose, onDeleted }: { meeting: Meeting; segments: TranscriptSegment[]; onClose: () => void; onDeleted: () => Promise<void> }) {
  const transcriptActions = useContext(TranscriptActions);
  const [exported, setExported] = useState("");
  const [current, setCurrent] = useState(segments);
  const [editing, setEditing] = useState<string | null>(null);
  const [draft, setDraft] = useState("");
  const [actionError, setActionError] = useState("");
  const exportTranscript = async (format: "markdown" | "text") => { try { setExported(await transcriptionApi.export(meeting.id, format)); setActionError(""); } catch (error) { setActionError(String(error)); } };
  const beginEdit = (segment: TranscriptSegment) => { setEditing(segment.id); setDraft(segment.displayText); };
  const saveEdit = async (segment: TranscriptSegment) => { const corrected = await transcriptionApi.correct(segment.id, draft); setCurrent((items) => items.map((item) => item.id === segment.id ? { ...item, displayText: corrected.displayText, activeCorrectionId: corrected.activeCorrectionId } : item)); setEditing(null); };
  const renameSpeaker = async (segment: TranscriptSegment) => { const currentLabel = segment.speakerLabel ?? "Speaker"; const newLabel = window.prompt(`Rename all “${currentLabel}” passages`, currentLabel); if (newLabel?.trim() && newLabel.trim() !== currentLabel) { try { await transcriptionApi.renameSpeaker(meeting.id, currentLabel, newLabel.trim()); setCurrent((items) => items.map((item) => item.speakerLabel === segment.speakerLabel ? { ...item, speakerLabel: newLabel.trim() } : item)); setActionError(""); } catch (error) { setActionError(String(error)); } } };
  const removeTranscript = async () => { if (window.confirm(`Delete the transcript for “${meeting.title}”? The recording will be kept.`)) { try { await transcriptionApi.delete(meeting.id); await onDeleted(); } catch (error) { setActionError(String(error)); } } };
  return <div className="dialog-backdrop" role="presentation" onMouseDown={onClose}><section className="transcript-dialog" role="dialog" aria-modal="true" aria-labelledby="transcript-title" onMouseDown={(event) => event.stopPropagation()}><div className="transcript-header"><div><p className="eyebrow">REVIEW TRANSCRIPT</p><h2 id="transcript-title">{meeting.title}</h2><p>{current.length} grouped, timestamped passages · generated locally</p></div><div className="transcript-header-actions"><button type="button" onClick={() => void exportTranscript("markdown")}>Export .md</button><button type="button" onClick={() => void exportTranscript("text")}>Export .txt</button><button className="danger" type="button" onClick={() => void removeTranscript()}>Delete transcript</button><button type="button" onClick={onClose}>Close</button></div></div>{actionError && <p className="transcript-error" role="alert">{actionError}</p>}{exported && <p className="export-path">Saved to {exported}</p>}<div className="transcript-body">{current.length === 0 ? <p>No speech was detected in this recording.</p> : current.map((segment) => <article key={segment.id}><button type="button" title="Play matching audio" onClick={() => transcriptActions.play(meeting, segment.sourceTrack === "system" ? "system" : segment.speakerLabel === "Microphone (original)" ? "mic_raw" : segment.speakerLabel === "Microphone (echo-reduced)" ? "mic" : selectedMicrophoneTrack(), segment.startMs)}>{timestampLabel(segment.startMs)}</button><div><div className="segment-heading"><strong>{segment.speakerLabel ?? "Speaker"}</strong>{editing !== segment.id && <div><button type="button" onClick={() => void renameSpeaker(segment)}>Rename speaker</button><button type="button" onClick={() => beginEdit(segment)}>Edit text</button></div>}</div>{editing === segment.id ? <div className="segment-editor"><textarea aria-label="Corrected transcript text" value={draft} onChange={(event) => setDraft(event.target.value)} /><div><button type="button" onClick={() => setEditing(null)}>Cancel</button><button type="button" disabled={!draft.trim()} onClick={() => void saveEdit(segment)}>Save correction</button></div></div> : <><p>{segment.displayText}</p>{segment.activeCorrectionId && <details><summary>Show preserved original</summary><p>{segment.sourceText}</p></details>}</>}</div></article>)}</div><p className="evidence-note"><Icon name="shield" size={15} /> Channel labels are automatic. Rename them when you know the person; corrections preserve the original transcription evidence.</p></section></div>;
}

function NotesDialog({ meeting, notes, onClose }: { meeting: Meeting; notes: MeetingNotes; onClose: () => void }) {
  const transcriptActions = useContext(TranscriptActions);
  const [exported, setExported] = useState("");
  const [actionError, setActionError] = useState("");
  const exportNotes = async (format: "markdown" | "text") => { try { setExported(await summaryApi.export(meeting.id, format)); setActionError(""); } catch (error) { setActionError(String(error)); } };
  const playEvidence = (evidence: EvidenceReference) => transcriptActions.play(meeting, evidence.sourceTrack === "system" ? "system" : selectedMicrophoneTrack(), evidence.startMs);
  const section = (title: string, items: GroundedNote[]) => <section className="notes-section"><h3>{title}</h3>{items.length === 0 ? <p className="notes-empty">Not identified in the transcript.</p> : items.map((item, index) => <article key={`${title}:${index}`}><p>{item.text}</p><div className="evidence-links">{item.evidence.map((evidence) => <button type="button" key={evidence.segmentId} onClick={() => playEvidence(evidence)}>{timestampLabel(evidence.startMs)} evidence</button>)}</div></article>)}</section>;
  return <div className="dialog-backdrop" role="presentation" onMouseDown={onClose}><section className="transcript-dialog notes-dialog" role="dialog" aria-modal="true" aria-labelledby="notes-title" onMouseDown={(event) => event.stopPropagation()}><div className="transcript-header"><div><p className="eyebrow">REVIEW MEETING NOTES</p><h2 id="notes-title">{meeting.title}</h2><p>{notes.strategy}</p></div><div className="transcript-header-actions"><button type="button" onClick={() => void exportNotes("markdown")}>Export .md</button><button type="button" onClick={() => void exportNotes("text")}>Export .txt</button><button type="button" onClick={onClose}>Close</button></div></div>{actionError && <p className="transcript-error" role="alert">{actionError}</p>}{exported && <p className="export-path">Saved to {exported}</p>}<div className="notes-body">{section("Overview", notes.overview)}{section("Topics", notes.topics)}{section("Decisions", notes.decisions)}<section className="notes-section"><h3>Actions</h3>{notes.actions.length === 0 ? <p className="notes-empty">Not identified in the transcript.</p> : notes.actions.map((action, index) => <article key={`action:${index}`}><p>{action.text}</p><small>Owner: {action.owner} · Due: {action.dueDate}</small><div className="evidence-links">{action.evidence.map((evidence) => <button type="button" key={evidence.segmentId} onClick={() => playEvidence(evidence)}>{timestampLabel(evidence.startMs)} evidence</button>)}</div></article>)}</section>{section("Questions", notes.questions)}{section("Risks", notes.risks)}{section("Next steps", notes.nextSteps)}</div><p className="evidence-note"><Icon name="shield" size={15} /> These are extractive local drafts, not authoritative conclusions. Every item links to transcript evidence; review before sharing.</p></section></div>;
}

function SettingsView({ onSaved, onError, onModelChanged }: { onSaved: () => void; onError: (value: string) => void; onModelChanged: () => void }) {
  const [reminder, setReminder] = useState(() => localStorage.getItem("transcrip-it.headset-reminder") !== "false");
  const [retention, setRetention] = useState(() => localStorage.getItem("transcrip-it.retention") ?? "forever");
  const [pack, setPack] = useState<TranscriptionModelPack>(selectedTranscriptionPack);
  const [microphoneTrack, setMicrophoneTrack] = useState<MicrophoneTrack>(selectedMicrophoneTrack);
  const [model, setModel] = useState<TranscriptionModelStatus | null>(null);
  const [diagnostics, setDiagnostics] = useState<WorkspaceDiagnostics | null>(null);
  const [installing, setInstalling] = useState(false);
  const selectedOption = packOptions.find((option) => option.id === pack) ?? packOptions[0];
  useEffect(() => { setModel(null); void transcriptionApi.modelStatus(pack).then(setModel).catch((error) => onError(String(error))); }, [pack, onError]);
  useEffect(() => { void diagnosticsApi.status().then(setDiagnostics).catch((error) => onError(String(error))); }, [onError]);
  const installModel = async () => { setInstalling(true); try { setModel(await transcriptionApi.installModel(pack)); onModelChanged(); onSaved(); } catch (error) { onError(String(error)); } finally { setInstalling(false); } };
  const save = (event: FormEvent) => { event.preventDefault(); localStorage.setItem("transcrip-it.headset-reminder", String(reminder)); localStorage.setItem("transcrip-it.retention", retention); localStorage.setItem(transcriptionPackKey, pack); localStorage.setItem(microphoneTrackKey, microphoneTrack); onSaved(); };
  return <section className="page-view"><div className="page-heading"><div><p className="eyebrow">LOCAL PREFERENCES</p><h1>Settings</h1><p>Control recording guidance, local models, and retention.</p></div></div><form className="settings-card" onSubmit={save}><div className="model-setup-guide"><div><span className="recommended-badge">ONE-TIME SETUP</span><strong>Install a local transcription model</strong><p>Models run entirely on this device. Installation needs an internet connection and may take several minutes; keep the app open until it finishes. Fast English also enables the live preview.</p></div><span className={`setup-step${model?.installed ? " complete" : ""}`}>{model === null ? "Checking…" : model.installed ? "Ready" : "Action needed"}</span></div><div className="setting-row"><div><strong>Headset reminder</strong><span>Show the audio-quality reminder before recording.</span></div><input aria-label="Headset reminder" type="checkbox" checked={reminder} onChange={(event) => setReminder(event.target.checked)} /></div><label className="setting-row"><div><strong>Microphone transcript source</strong><span>{microphoneTrack === "mic_raw" ? "Voice-safe original; preserves speech but may include speaker bleed." : "Reduces speaker bleed but can mute speech during loud overlap."}</span></div><select aria-label="Microphone transcript source" value={microphoneTrack} onChange={(event) => setMicrophoneTrack(event.target.value as MicrophoneTrack)}><option value="mic_raw">Original mic (voice-safe)</option><option value="mic">Echo-reduced mic (experimental)</option></select></label><label className="setting-row"><div><strong>Transcription quality</strong><span>{selectedOption.detail} · approximately {selectedOption.size}</span></div><select aria-label="Transcription quality" value={pack} onChange={(event) => setPack(event.target.value as TranscriptionModelPack)}>{packOptions.map((option) => <option key={option.id} value={option.id}>{option.label}</option>)}</select></label><div className="setting-row"><div><strong>{model?.pack ?? selectedOption.label} model</strong><span>{model?.installed ? `${Math.round((model.modelBytes ?? 0) / 1024 / 1024)} MB · ${model.engineVersion}` : `Not installed · approximately ${selectedOption.size}`}</span></div>{model?.installed ? <span className="model-status installed">Installed</span> : <button className="secondary-button" type="button" disabled={installing || !transcriptionApi.available || model === null} onClick={() => void installModel()}>{installing ? "Installing locally…" : "Install model"}</button>}</div>{installing && <p className="install-progress" role="status">Downloading and building the local engine. This can take several minutes; do not close Transcrip-it.</p>}<section className="diagnostics-panel" aria-label="Local diagnostics"><div className="diagnostics-heading"><div><strong>Local diagnostics</strong><span>Counts and operational codes only; meeting content is excluded.</span></div><button type="button" onClick={() => void diagnosticsApi.status().then(setDiagnostics).catch((error) => onError(String(error)))}>Refresh</button></div>{diagnostics ? <div className="diagnostic-grid"><div><span>Local storage used</span><strong>{byteLabel(diagnostics.storageBytes)}</strong><small>{byteLabel(diagnostics.recordingBytes)} recordings · {byteLabel(diagnostics.databaseBytes)} database</small></div><div><span>Workspace health</span><strong>{diagnostics.failedMeetingCount === 0 ? "Healthy" : `${diagnostics.failedMeetingCount} need attention`}</strong><small>{diagnostics.meetingCount} local meetings</small></div><div><span>Processing jobs</span><strong>{diagnostics.recentJobErrors.length === 0 ? "No errors" : `${diagnostics.recentJobErrors.length} recent errors`}</strong><small>{diagnostics.recentJobErrors.length === 0 ? "No failed background jobs recorded" : diagnostics.recentJobErrors.map((item) => `${item.jobKind}: ${item.errorCode}`).join(" · ")}</small></div></div> : <p className="diagnostics-loading">Checking local workspace…</p>}</section><label className="setting-row"><div><strong>Keep meeting data</strong><span>Automatic retention will never remove data before this period.</span></div><select value={retention} onChange={(event) => setRetention(event.target.value)}><option value="forever">Until I delete it</option><option value="365">One year</option><option value="90">90 days</option><option value="30">30 days</option></select></label><div className="privacy-setting"><Icon name="shield" /><div><strong>Local processing is on</strong><span>Meeting content is not sent to a cloud service.</span></div></div><button className="primary-button" type="submit">Save settings</button></form></section>;
}

function App() {
  const [activeView, setActiveView] = useState<View>("home"); const [meetings, setMeetings] = useState<Meeting[]>([]); const [includeArchived, setIncludeArchived] = useState(false); const [search, setSearch] = useState(""); const [statusFilter, setStatusFilter] = useState<MeetingFilters["status"]>("all"); const [tagFilter, setTagFilter] = useState(""); const [participantFilter, setParticipantFilter] = useState(""); const [dateFilter, setDateFilter] = useState<MeetingFilters["dateRange"]>("all"); const [transcriptMatches, setTranscriptMatches] = useState<TranscriptSearchResult[]>([]); const [loading, setLoading] = useState(true); const [error, setError] = useState(""); const [notice, setNotice] = useState(""); const [deviceWarnings, setDeviceWarnings] = useState<string[]>([]); const [fastModel, setFastModel] = useState<TranscriptionModelStatus | null>(null); const [recordingMeeting, setRecordingMeeting] = useState<Meeting | null>(null); const [recordingStatus, setRecordingStatus] = useState<RecordingStatus | null>(null); const [liveLines, setLiveLines] = useState<LiveTranscriptLine[]>([]); const [liveCheckedThroughMs, setLiveCheckedThroughMs] = useState(0); const [liveError, setLiveError] = useState(""); const [previewing, setPreviewing] = useState(false); const [playback, setPlayback] = useState<PlaybackStatus | null>(null); const [transcribingId, setTranscribingId] = useState<string | null>(null); const [transcriptionProgress, setTranscriptionProgress] = useState<TranscriptionProgress | null>(null); const [openTranscript, setOpenTranscript] = useState<{ meeting: Meeting; segments: TranscriptSegment[] } | null>(null); const [openNotes, setOpenNotes] = useState<{ meeting: Meeting; notes: MeetingNotes } | null>(null);
  const loadMeetings = useCallback(async () => { setLoading(true); try { setMeetings(await meetingApi.list(includeArchived)); setError(""); } catch (reason) { setError(String(reason)); } finally { setLoading(false); } }, [includeArchived]);
  const refreshFastModel = useCallback(() => { if (transcriptionApi.available) void transcriptionApi.modelStatus("fast").then(setFastModel).catch((reason) => setError(String(reason))); }, []);
  useEffect(() => { void loadMeetings(); }, [loadMeetings]);
  useEffect(() => { refreshFastModel(); }, [refreshFastModel]);
  useEffect(() => { if (!recordingApi.available) return; void recordingApi.status().then(async (status) => { if (status.active && status.meetingId) { const found = (await meetingApi.list(true)).find((meeting) => meeting.id === status.meetingId); if (found) { setRecordingMeeting(found); setRecordingStatus(status); setActiveView("record"); } return; } const recovered = await recordingApi.recoverInterrupted(); if (recovered > 0) { setNotice(`${recovered} interrupted recording${recovered === 1 ? " was" : "s were"} recovered. Its safe audio can now be played or transcribed.`); await loadMeetings(); } }).catch((reason) => setError(String(reason))); }, []);
  useEffect(() => { if (!recordingMeeting) return; const timer = window.setInterval(() => { void recordingApi.status().then(setRecordingStatus).catch((reason) => setError(String(reason))); }, 1000); return () => window.clearInterval(timer); }, [recordingMeeting]);
  useEffect(() => { if (!playback?.active) return; const timer = window.setInterval(() => { void recordingApi.playbackStatus().then(setPlayback).catch((reason) => setError(String(reason))); }, 500); return () => window.clearInterval(timer); }, [playback?.active, playback?.meetingId, playback?.track]);
  useEffect(() => { if (!transcribingId) { setTranscriptionProgress(null); return; } const refresh = () => { void transcriptionApi.status().then(setTranscriptionProgress).catch((reason) => setError(String(reason))); }; refresh(); const timer = window.setInterval(refresh, 500); return () => window.clearInterval(timer); }, [transcribingId]);
  useEffect(() => {
    if (!recordingMeeting) return;
    let cancelled = false;
    let timer = 0;
    const meetingId = recordingMeeting.id;
    const refresh = async () => {
      if (cancelled) return;
      setPreviewing(true);
      try {
        const preview = await transcriptionApi.livePreview(meetingId, selectedMicrophoneTrack());
        if (!cancelled) {
          setLiveCheckedThroughMs(preview.checkedThroughMs);
          setLiveLines((existing) => {
            const merged = new Map(existing.map((line) => [`${line.trackId}:${line.chunkIndex}:${line.windowIndex}`, line]));
            preview.lines.forEach((line) => merged.set(`${line.trackId}:${line.chunkIndex}:${line.windowIndex}`, line));
            return [...merged.values()].sort((left, right) => left.startMs - right.startMs || left.trackId.localeCompare(right.trackId));
          });
          setLiveError("");
        }
      } catch (reason) {
        if (!cancelled) setLiveError(String(reason));
      } finally {
        if (!cancelled) {
          setPreviewing(false);
          timer = window.setTimeout(() => void refresh(), 2_500);
        }
      }
    };
    timer = window.setTimeout(() => void refresh(), 2_500);
    return () => { cancelled = true; window.clearTimeout(timer); };
  }, [recordingMeeting?.id]);
  useEffect(() => { const timer = window.setTimeout(() => { void transcriptionApi.search(search).then(setTranscriptMatches).catch((reason) => setError(String(reason))); }, 180); return () => window.clearTimeout(timer); }, [search]);
  const availableTags = useMemo(() => [...new Set(meetings.flatMap((meeting) => meeting.tags))].sort((left, right) => left.localeCompare(right)), [meetings]);
  const availableParticipants = useMemo(() => [...new Set(meetings.flatMap((meeting) => meeting.participantLabels ?? []))].sort((left, right) => left.localeCompare(right)), [meetings]);
  const filtered = useMemo(() => meetings.filter((meeting) => meetingMatchesFilters(meeting, { query: search, status: statusFilter, tag: tagFilter, participant: participantFilter, dateRange: dateFilter })), [meetings, search, statusFilter, tagFilter, participantFilter, dateFilter]);
  const clearFilters = () => { setStatusFilter("all"); setTagFilter(""); setParticipantFilter(""); setDateFilter("all"); };
  const goToRecord = () => setActiveView("record");
  const startRecording = async (title: string, options: StartRecordingOptions) => { const id = crypto.randomUUID(); const meeting = await meetingApi.create({ id, idempotencyKey: `create-${id}`, title }); try { const status = await recordingApi.start(id, true, options); setLiveLines([]); setLiveCheckedThroughMs(0); setLiveError(""); setRecordingMeeting({ ...meeting, state: "recording" }); setRecordingStatus(status); await loadMeetings(); } catch (reason) { try { await meetingApi.delete(id); } catch { /* Preserve the original capture error. */ } await loadMeetings(); throw reason; } };
  const stopRecording = async () => { if (!recordingMeeting) return; const completed = await recordingApi.stop(recordingMeeting.id); setRecordingMeeting(null); setRecordingStatus(null); setLiveLines([]); setLiveCheckedThroughMs(0); setLiveError(""); await loadMeetings(); setNotice(`Recording saved locally (${durationLabel(completed.durationMs)}).`); setActiveView("meetings"); };
  const togglePause = async () => { if (!recordingMeeting || !recordingStatus) return; const status = recordingStatus.paused ? await recordingApi.resume(recordingMeeting.id) : await recordingApi.pause(recordingMeeting.id); setRecordingStatus(status); };
  const viewTranscript = async (meeting: Meeting) => { try { setOpenTranscript({ meeting, segments: await transcriptionApi.list(meeting.id) }); } catch (reason) { setError(String(reason)); } };
  const viewNotes = async (meeting: Meeting) => { try { setOpenNotes({ meeting, notes: await summaryApi.generate(meeting.id) }); } catch (reason) { setError(String(reason)); } };
  const playRecording = async (meeting: Meeting, track: AudioTrack, startMs = 0) => { try { setPlayback(await recordingApi.play(meeting.id, track, startMs)); } catch (reason) { setError(String(reason)); } };
  const stopPlayback = async () => { try { setPlayback(await recordingApi.stopPlayback()); } catch (reason) { setError(String(reason)); } };
  const transcribe = async (meeting: Meeting) => { setTranscribingId(meeting.id); setTranscriptionProgress({ active: true, meetingId: meeting.id, stage: "Preparing audio", percent: 5 }); setNotice("Transcribing each audio channel locally. Audio and text stay on this device."); try { const segments = await transcriptionApi.transcribe(meeting.id, selectedTranscriptionPack(), selectedMicrophoneTrack()); await loadMeetings(); setOpenTranscript({ meeting: { ...meeting, transcriptSegmentCount: segments.length }, segments }); setNotice("Local transcription complete with grouped passages and channel labels."); } catch (reason) { setError(`${String(reason)} The preserved recording can be retried from Meetings.`); await loadMeetings(); } finally { setTranscribingId(null); } };
  const openSearchResult = (result: TranscriptSearchResult) => { const meeting = meetings.find((candidate) => candidate.id === result.meetingId); if (meeting) void viewTranscript(meeting); };
  const recordedMinutes = Math.round(meetings.reduce((sum, meeting) => sum + (meeting.durationMs ?? 0), 0) / 60_000);
  const playbackMeeting = playback?.meetingId ? meetings.find((meeting) => meeting.id === playback.meetingId) : null;
  const audioWarnings = [...new Set([...deviceWarnings, ...recordingWarningMessages(recordingStatus)])];
  return <TranscriptActions.Provider value={{ open: (meeting) => void viewTranscript(meeting), notes: (meeting) => void viewNotes(meeting), transcribe: (meeting) => void transcribe(meeting), play: (meeting, track, startMs) => void playRecording(meeting, track, startMs), stopPlayback: () => void stopPlayback(), playback, transcribingId }}><div className="app-shell">
    {(error || notice || audioWarnings.length > 0) && <div className="toast-stack" aria-live="assertive">{error && <div className="message error toast" role="alert"><span>{error}</span><button type="button" onClick={() => setError("")}>Dismiss</button></div>}{audioWarnings.map((warning) => <div className="message warning toast" role="alert" key={warning}><span>{warning}</span></div>)}{notice && <div className="message success toast" role="status"><span>{notice}</span><button type="button" onClick={() => setNotice("")}>Dismiss</button></div>}</div>}
    <aside className="sidebar"><div className="brand"><div className="brand-mark" aria-hidden="true"><span /><span /><span /><span /><span /></div><span>Transcrip<span className="brand-accent">·it</span></span></div><nav className="primary-nav" aria-label="Primary navigation">{navItems.map((item) => <button className={activeView === item.id ? "nav-item active" : "nav-item"} key={item.id} onClick={() => setActiveView(item.id)} type="button"><Icon name={item.icon} /><span>{item.label}</span></button>)}</nav><div className="sidebar-footer"><div className="local-status"><span className="status-dot" /><div><strong>Local workspace</strong><span>Your data stays on this device</span></div></div><div className="storage-row"><span>Meetings</span><span>{meetings.length} local</span></div><div className="storage-track"><span /></div></div></aside>
    <main className="main-panel"><header className="topbar"><div className="mobile-brand">Transcrip<span>·it</span></div><label className="search-box"><Icon name="search" size={18} /><span className="sr-only">Search meetings</span><input type="search" placeholder="Search meetings…" value={search} onChange={(event) => setSearch(event.target.value)} onFocus={() => setActiveView("meetings")} /><kbd>⌘ K</kbd></label><div className="privacy-pill"><Icon name="shield" size={16} /> Private by default</div><button className="avatar" type="button" aria-label="Local profile">JA</button></header>
      <div className="content">{playback?.active && <div className="playback-bar" role="status" aria-live="polite"><span className="playback-indicator" aria-hidden="true"><i /><i /><i /></span><div><strong>Playing {playback.track === "system" ? "meeting audio" : playback.track === "mic_raw" ? "original microphone" : "echo-reduced microphone"}</strong><span>{playbackMeeting?.title ?? "Recording"} · {timestampLabel(playback.positionMs)}</span></div><button type="button" onClick={() => void stopPlayback()}>Stop audio</button></div>}{transcribingId && <div className="processing-bar" role="status" aria-live="polite"><Icon name="sparkles" size={18} /><div><strong>{transcriptionProgress?.stage ?? "Starting local transcription"}</strong><span>{transcriptionProgress?.percent ?? 0}% · keep Transcrip-it open; the recording is preserved if processing fails</span><i><b style={{ width: `${transcriptionProgress?.percent ?? 0}%` }} /></i></div></div>}
        {activeView === "home" && <><section className="hero-row"><div><p className="eyebrow">YOUR MEETING WORKSPACE</p><h1>Good morning</h1><p className="hero-copy">Capture the conversation. Keep the important parts.</p></div><button className="primary-button" type="button" onClick={goToRecord}><Icon name="plus" size={18} /> New recording</button></section>{fastModel && !fastModel.installed && <section className="setup-alert" role="status"><Icon name="sparkles" size={22} /><div><strong>Finish transcription setup</strong><span>Install the Fast English model once to enable local live and final transcripts. Recording remains available without it.</span></div><button type="button" onClick={() => setActiveView("settings")}>Set up transcription</button></section>}<section className="metric-grid" aria-label="Workspace summary"><article className="metric-card"><div className="metric-icon violet"><Icon name="clock" /></div><div><span>MEETINGS</span><strong>{meetings.filter((meeting) => meeting.state !== "archived").length}</strong><small>Local</small></div></article><article className="metric-card"><div className="metric-icon blue"><Icon name="record" /></div><div><span>RECORDED</span><strong>{recordedMinutes}m</strong><small>All time</small></div></article><article className="metric-card"><div className="metric-icon amber"><Icon name="sparkles" /></div><div><span>READY</span><strong>{meetings.filter((meeting) => meeting.state === "ready").length}</strong><small>Meetings</small></div></article></section><section className="headset-card"><div className="headset-art"><Icon name="headphones" size={29} /></div><div className="headset-copy"><span className="recommended-badge">RECOMMENDED</span><h2>Use a headset for the clearest transcript</h2><p>A headset helps separate your voice from meeting audio and improves speaker accuracy.</p></div><button className="text-button" type="button" onClick={() => setActiveView("settings")}>Audio settings <Icon name="chevron" size={16} /></button></section><section className="section-block"><div className="section-heading"><div><h2>Recent meetings</h2><p>Your latest local meetings.</p></div><button className="text-button" type="button" onClick={() => setActiveView("meetings")}>View all <Icon name="chevron" size={16} /></button></div>{loading ? <p className="loading-copy">Loading your library…</p> : meetings.length === 0 ? <EmptyLibrary onRecord={goToRecord} /> : <div className="meeting-list">{meetings.slice(0, 3).map((meeting) => <MeetingCard key={meeting.id} meeting={meeting} onChanged={loadMeetings} onError={setError} />)}</div>}</section></>}
        {activeView === "meetings" && <section className="page-view"><div className="page-heading"><div><p className="eyebrow">LOCAL LIBRARY</p><h1>Meetings</h1><p>Organize, filter, archive, and permanently remove recordings stored on this device.</p></div><button className="primary-button" type="button" onClick={goToRecord}><Icon name="plus" size={18} /> New recording</button></div><div className="meeting-filters" aria-label="Meeting filters"><label><span>Date</span><select aria-label="Filter by date" value={dateFilter} onChange={(event) => setDateFilter(event.target.value as MeetingFilters["dateRange"])}><option value="all">Any date</option><option value="today">Today</option><option value="7">Last 7 days</option><option value="30">Last 30 days</option></select></label><label><span>Status</span><select aria-label="Filter by status" value={statusFilter} onChange={(event) => setStatusFilter(event.target.value as MeetingFilters["status"])}><option value="all">Any status</option><option value="draft">Draft</option><option value="ready">Ready</option><option value="failed">Recovered</option><option value="archived">Archived</option></select></label><label><span>Tag</span><select aria-label="Filter by tag" value={tagFilter} onChange={(event) => setTagFilter(event.target.value)}><option value="">Any tag</option>{availableTags.map((tag) => <option value={tag} key={tag}>{tag}</option>)}</select></label><label><span>Participant</span><select aria-label="Filter by participant" value={participantFilter} onChange={(event) => setParticipantFilter(event.target.value)}><option value="">Any participant</option>{availableParticipants.map((participant) => <option value={participant} key={participant}>{participant}</option>)}</select></label><label className="archive-toggle"><input type="checkbox" checked={includeArchived} onChange={(event) => setIncludeArchived(event.target.checked)} /> Show archived</label><button type="button" onClick={clearFilters} disabled={statusFilter === "all" && !tagFilter && !participantFilter && dateFilter === "all"}>Clear filters</button><small>{filtered.length} of {meetings.length} meetings</small></div>{loading ? <p className="loading-copy">Loading your library…</p> : filtered.length === 0 ? <div className="filtered-empty"><h3>No meetings match these filters</h3><p>Change or clear the filters to see more of your library.</p><button className="secondary-button" type="button" onClick={clearFilters}>Clear filters</button></div> : <div className="meeting-list">{filtered.map((meeting) => <MeetingCard key={meeting.id} meeting={meeting} onChanged={loadMeetings} onError={setError} />)}</div>}</section>}
        {activeView === "record" && (recordingMeeting && recordingStatus ? <ActiveRecording meeting={recordingMeeting} status={recordingStatus} liveLines={liveLines} liveCheckedThroughMs={liveCheckedThroughMs} liveError={liveError} previewing={previewing} onStop={stopRecording} onTogglePause={togglePause} /> : <RecordSetup onStart={startRecording} onError={setError} onWarnings={setDeviceWarnings} />)}{activeView === "settings" && <SettingsView onSaved={() => setNotice("Settings saved on this device.")} onError={setError} onModelChanged={refreshFastModel} />}
        {activeView === "meetings" && search.trim().length >= 2 && transcriptMatches.length > 0 && <section className="search-results"><h2>Transcript matches</h2>{transcriptMatches.map((result) => <button type="button" key={result.segmentId} onClick={() => openSearchResult(result)}><span><strong>{result.meetingTitle}</strong><small>{timestampLabel(result.startMs)}</small></span><p>{result.snippet.replaceAll("<mark>", "").replaceAll("</mark>", "")}</p></button>)}</section>}
      </div></main>
    <nav className="mobile-nav" aria-label="Mobile navigation">{navItems.map((item) => <button className={activeView === item.id ? "active" : ""} key={item.id} onClick={() => setActiveView(item.id)} type="button"><Icon name={item.icon} size={19} /><span>{item.label}</span></button>)}</nav>
    {openTranscript && <TranscriptDialog meeting={openTranscript.meeting} segments={openTranscript.segments} onClose={() => setOpenTranscript(null)} onDeleted={async () => { setOpenTranscript(null); await loadMeetings(); setNotice("Transcript deleted. The recording is still available for a new transcription."); }} />}
    {openNotes && <NotesDialog meeting={openNotes.meeting} notes={openNotes.notes} onClose={() => setOpenNotes(null)} />}
  </div></TranscriptActions.Provider>;
}

export default App;
